from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import List, Optional

import torch
from torch import Tensor, nn


def average_attention_heads(attention: Tensor) -> Tensor:
    # Final-layer self-attention averaged across heads, as described in the paper.
    # Supports shapes:
    #   [B, H, M, M] -> [B, M, M]
    #   [H, M, M]    -> [M, M]
    #   [M, M]       -> [M, M]
    if attention.dim() == 4:
        return attention.mean(dim=1)
    if attention.dim() == 3:
        return attention.mean(dim=0)
    if attention.dim() == 2:
        return attention
    raise ValueError(f"Unsupported attention shape: {tuple(attention.shape)}")


def normalize_attention(attention: Tensor, eps: float = 1e-8) -> Tensor:
    # Make rows sum to 1 so A_ij can be used as a soft interaction coefficient.
    row_sum = attention.sum(dim=-1, keepdim=True).clamp_min(eps)
    return attention / row_sum


def confidence_from_logits(logits: Tensor) -> Tensor:
    # Eq. (1): c_i = max_x p_theta(x_i | x_{\bar M})
    probs = torch.softmax(logits, dim=-1)
    return probs.max(dim=-1).values


def entropy_from_probs(probs: Tensor, eps: float = 1e-12) -> Tensor:
    # H(p) = - sum_x p(x) log p(x)
    return -(probs * probs.clamp_min(eps).log()).sum(dim=-1)


@dataclass
class SelectionResult:
    selected_indices: Tensor
    selected_confidence: Tensor
    selected_entropy: Optional[Tensor]
    selected_utilities: Tensor
    final_utilities: Tensor
    selected_mask: Tensor
    stopped_by_rule: bool


class AdmissibilityRule(ABC):
    @abstractmethod
    def is_admissible(self, selected_confidence: Tensor, selected_entropy: Optional[Tensor] = None) -> bool:
        raise NotImplementedError


class TopKAdmissibilityRule(AdmissibilityRule):
    def __init__(self, k: int) -> None:
        self.k = int(k)

    def is_admissible(self, selected_confidence: Tensor, selected_entropy: Optional[Tensor] = None) -> bool:
        # Eq. (5): |S ∪ {i*}| ≤ k
        return int(selected_confidence.numel()) <= self.k


class FastDLLMAdmissibilityRule(AdmissibilityRule):
    def __init__(self, f: float) -> None:
        self.f = float(f)

    def is_admissible(self, selected_confidence: Tensor, selected_entropy: Optional[Tensor] = None) -> bool:
        # Eq. (6): |S| (1 - min_{s∈S} c_s) < f
        if selected_confidence.numel() == 0:
            return True
        size = float(selected_confidence.numel())
        min_conf = float(selected_confidence.min().item())
        return size * (1.0 - min_conf) < self.f


class EntropyBudgetAdmissibilityRule(AdmissibilityRule):
    def __init__(self, gamma: float) -> None:
        self.gamma = float(gamma)

    def is_admissible(self, selected_confidence: Tensor, selected_entropy: Optional[Tensor] = None) -> bool:
        # Eq. (7): sum H(p_s) - max H(p_s) < gamma
        if selected_entropy is None:
            raise ValueError("EntropyBudgetAdmissibilityRule requires selected_entropy.")
        if selected_entropy.numel() == 0:
            return True
        total_entropy = float(selected_entropy.sum().item())
        max_entropy = float(selected_entropy.max().item())
        return (total_entropy - max_entropy) < self.gamma


class AttentionDiscountedAdaptiveSampler(nn.Module):
    def __init__(self, alpha: float = 40.0, normalize_attn: bool = True) -> None:
        super().__init__()
        self.alpha = float(alpha)
        self.normalize_attn = bool(normalize_attn)

    def select(
        self,
        confidence: Tensor,
        attention: Tensor,
        admissibility_rule: AdmissibilityRule,
        entropy: Optional[Tensor] = None,
    ) -> SelectionResult:
        # Greedy subset construction:
        #   u(i | S, A) = c_i - alpha * sum_{s in S} A_is (1 - c_s)
        # where candidates are appended in descending current utility.
        if confidence.dim() != 1:
            raise ValueError("confidence must be a 1D tensor over masked positions.")
        if attention.dim() != 2 or attention.shape[0] != attention.shape[1]:
            raise ValueError("attention must be a square 2D tensor over masked positions.")
        if attention.shape[0] != confidence.shape[0]:
            raise ValueError("attention and confidence must agree on the number of masked positions.")

        if entropy is not None and entropy.shape != confidence.shape:
            raise ValueError("entropy must have the same shape as confidence.")

        if self.normalize_attn:
            attention = normalize_attention(attention)

        num_positions = confidence.shape[0]
        current_utilities = confidence.clone()
        remaining = torch.ones(num_positions, dtype=torch.bool, device=confidence.device)

        selected_indices: List[int] = []
        selected_utilities: List[Tensor] = []
        stopped_by_rule = False

        while bool(remaining.any()):
            # Select argmax over remaining candidates.
            candidate_utilities = current_utilities.masked_fill(~remaining, float("-inf"))
            i_star = int(torch.argmax(candidate_utilities).item())

            # Build the prospective selected set S ∪ {i*}.
            new_selected_indices = selected_indices + [i_star]
            new_selected_conf = confidence[torch.tensor(new_selected_indices, device=confidence.device)]

            if entropy is None:
                new_selected_entropy = None
            else:
                new_selected_entropy = entropy[torch.tensor(new_selected_indices, device=confidence.device)]

            if not admissibility_rule.is_admissible(new_selected_conf, new_selected_entropy):
                stopped_by_rule = True
                break

            selected_indices.append(i_star)
            selected_utilities.append(current_utilities[i_star].detach() if not current_utilities[i_star].requires_grad else current_utilities[i_star])

            # Remove the chosen token from future consideration.
            remaining[i_star] = False

            # Incremental update:
            #   for every remaining i, u(i) <- u(i) - alpha * A_is * (1 - c_s)
            # with s = i_star.
            if bool(remaining.any()):
                current_utilities[remaining] = current_utilities[remaining] - self.alpha * attention[remaining, i_star] * (1.0 - confidence[i_star])

        selected_indices_tensor = torch.tensor(selected_indices, dtype=torch.long, device=confidence.device)
        selected_mask = torch.zeros(num_positions, dtype=torch.bool, device=confidence.device)
        if selected_indices_tensor.numel() > 0:
            selected_mask[selected_indices_tensor] = True

        if selected_indices_tensor.numel() > 0:
            selected_confidence = confidence[selected_indices_tensor]
            selected_entropy = None if entropy is None else entropy[selected_indices_tensor]
            selected_utilities_tensor = torch.stack(selected_utilities)
        else:
            selected_confidence = confidence.new_empty((0,))
            selected_entropy = None if entropy is None else entropy.new_empty((0,))
            selected_utilities_tensor = confidence.new_empty((0,))

        return SelectionResult(
            selected_indices=selected_indices_tensor,
            selected_confidence=selected_confidence,
            selected_entropy=selected_entropy,
            selected_utilities=selected_utilities_tensor,
            final_utilities=current_utilities,
            selected_mask=selected_mask,
            stopped_by_rule=stopped_by_rule,
        )

    def select_batch(
        self,
        confidence: Tensor,
        attention: Tensor,
        admissibility_rule: AdmissibilityRule,
        entropy: Optional[Tensor] = None,
    ) -> List[SelectionResult]:
        # Batch wrapper that runs the single-state greedy sampler independently per example.
        if confidence.dim() != 2:
            raise ValueError("confidence must be [B, M].")
        if attention.dim() != 3:
            raise ValueError("attention must be [B, M, M].")
        if confidence.shape[0] != attention.shape[0] or confidence.shape[1] != attention.shape[1]:
            raise ValueError("Batch shapes of confidence and attention must agree.")

        if entropy is not None and entropy.shape != confidence.shape:
            raise ValueError("entropy must have shape [B, M] when provided.")

        results: List[SelectionResult] = []
        for b in range(confidence.shape[0]):
            entropy_b = None if entropy is None else entropy[b]
            results.append(self.select(confidence[b], attention[b], admissibility_rule, entropy_b))
        return results

